ce .close-btn__icon::after { content: ""; position: absolute; top: 50%; left: 0; width: 16px; height: 1.5px; background: #ffffff; } .bookmark-experience .close-btn__icon::before { transform: translateY(-50%) rotate(45deg); } .bookmark-experience .close-btn__icon::after { transform: translateY(-50%) rotate(-45deg); } .bookmark-experience .logo-row { display: flex; align-items: center; justify-content: center; margin: 0 0 24px; } .bookmark-experience .logo-premium-image { display: block; height: 24px; width: 272px; max-width: 86%; object-fit: contain; } .bookmark-experience .headline { font-family: "Independent Serif", Georgia, serif; font-weight: 500; font-size: 28px; line-height: 32px; letter-spacing: -0.5px; color: #ffffff; margin: 0 0 16px; } .bookmark-experience .body-text { font-family: "Independent Serif", Georgia, serif; font-weight: 400; font-size: 16px; line-height: 22px; letter-spacing: -0.3px; color: #ffffff; margin: 0 0 24px; } .bookmark-experience .subscribe-link { display: flex; align-items: center; justify-content: center; width: 100%; height: 42px; padding: 12px 16px; background: #ffffff; color: #76071f; border-radius: 4px; font-family: "Independent Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; font-size: 14px; font-weight: 500; line-height: 16px; letter-spacing: -0.5px; text-transform: uppercase; text-decoration: none; } .bookmark-experience .subscribe-link:hover, .bookmark-experience .subscribe-link:focus { background: #f0e6e8; color: #76071f; } .bookmark-experience .login-copy { margin: 12px 0 0; font-family: "Independent Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; font-size: 14px; line-height: 18px; letter-spacing: -0.5px; color: #ffffff; } .bookmark-experience .login-link { color: #ffffff; text-decoration: underline; cursor: pointer; } @media screen and (min-width: 600px) { .bookmark-experience { padding: 16px; } .bookmark-experience .modal { max-width: 520px; padding: 40px 48px 32px; } .bookmark-experience .close-btn, .bookmark-experience .close-btn__icon, .bookmark-experience .close-btn__icon::before, .bookmark-experience .close-btn__icon::after { width: 16px; } .bookmark-experience .close-btn { top: 16px; right: 16px; } .bookmark-experience .logo-premium-image { height: 28px; width: 320px; } .bookmark-experience .headline { font-size: 32px; line-height: 36px; letter-spacing: -0.75px; margin-bottom: 16px; } .bookmark-experience .body-text { font-size: 16px; line-height: 22px; margin-bottom: 28px; } } }

